const fs = require('fs');
const zlib = require('zlib');
const path = '/workspace/testbed/docs/customer_report.docx';

// .docx is a ZIP file; we'll parse it manually
const buf = fs.readFileSync(path);

// Find local file headers and extract word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  // Local file header signature: 0x04034b50
  if (buf.readUInt32LE(offset) !== 0x04034b50) break;
  const compressionMethod = buf.readUInt16LE(offset + 8);
  const compressedSize = buf.readUInt32LE(offset + 18);
  const uncompressedSize = buf.readUInt32LE(offset + 22);
  const fnLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const filename = buf.slice(offset + 30, offset + 30 + fnLen).toString('utf8');
  const dataStart = offset + 30 + fnLen + extraLen;
  const dataEnd = dataStart + compressedSize;

  if (filename === 'word/document.xml') {
    let xml;
    if (compressionMethod === 8) {
      xml = zlib.inflateRawSync(buf.slice(dataStart, dataEnd)).toString('utf8');
    } else {
      xml = buf.slice(dataStart, dataEnd).toString('utf8');
    }
    // Strip XML tags and extract text
    const text = xml.replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, '').trim();
    console.log(text);
    process.exit(0);
  }
  offset = dataEnd;
}
console.error('word/document.xml not found in the .docx file');
"
